using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Imaging;using System.Diagnostics;using System.Globalization;using System.IO;using System.Linq;using System.Reflection;using System.Text.RegularExpressions;using TradeLedgerProbeB;
namespace BOfflineTests {internal static class LedgerUiConsistencyTests {
 const string NativeGeo="native exact observed PF 5D4B;system5D49/sector5D4A;fixture";
 static LedgerObservation Place(string root,int id,string pf="Fixture Delta IV Moon B"){
  var c=LedgerContext.Create(Path.Combine(root,"owned-ui"),pf,"Fixture Delta","SinglePlayer");c.Geography=new LedgerGeography{BodyKind="Moon",SystemCoordinates="0,0,0",SectorCoordinates=pf=="Fixture Delta IV Moon B"?"10,0,0":"20,0,0",GroupName="Fixture Delta IV",Source=NativeGeo};
  return new LedgerObservation{Context=c,ObserverPlayer=1002,Kind="place-observed",Utc="2026-11-16T12:00:00Z",DiscoveredObject=new LedgerObjectFact{Player=1002,NativeId=id,NativeName="Colony",DisplayName="A long discovered place "+id,ContentIdentity="RE2 Build 46",Evidence="local-poi-discovery",FactionGroup=7,FactionId=0,X=id*10,Y=0,Z=0,PositionSource="bound instance position1B3A"}};
 }
 static LedgerObservation Device(LedgerContext c,int id,int item,double rate,long stock,int aux=0){var p=new LedgerProductionSnapshot{Key="device"+id,Kind="producer",Player=1002,Family="AutoMiner",Definition=1110,Device="Auto Miner T3",Resource="Ore "+item,Epoch=c.WorldKey,Tick=1000,FuelTick=1000,FuelSeconds=200000,Period=72000,NextTick=73000,Capacity=100000,Running=true,NextItem=item,ShownQuality=rate+"/h",Outputs=new List<LedgerProductionOutput>{new LedgerProductionOutput{Item=item,Auxiliary=aux,Name="Ore "+item,Stock=stock}}};return new LedgerObservation{Kind="production",Context=c,Production=p,Utc="2026-11-16T12:00:00Z"};}
 internal static void Run(Action<bool,string> check,string root){int count=0;Action<bool,string> ok=(pass,n)=>{check(pass,"UI consistency: "+n);count++;};
  ok(LedgerJournalUi.TabOrder.Select(i=>LedgerJournalUi.Tabs[i]).Take(4).SequenceEqual(new[]{"Market","Requests","Production","Destinations"}),"leading display tabs ordered without changing stored IDs");
  ok(LedgerJournalUi.TabOrder.OrderBy(i=>i).SequenceEqual(Enumerable.Range(0,8)),"every existing view retained once");
  foreach(int i in Enumerable.Range(0,8)){string saved=null;var prefs=new LedgerTabPreference(()=>saved,s=>saved=s);prefs.Select(i);ok(new LedgerTabPreference(()=>saved).Index==i,"stable tab preference "+i);}
  ok(LedgerJournalUi.Dropdown==" \u25BE","same existing triangle indicator replaces literal v");
  var first=Place(root,1);var c=first.Context;var prefsService=new LedgerServicePreferences();var places=new LedgerProductionPlaces(c.WorldKey,new[]{c});
  var devices=new[]{Device(c,1,40,31,1595),Device(c,2,40,50,100),Device(c,3,41,17,25),Device(c,4,40,7,9,1)};
  var sum=LedgerProductionServices.Overview(devices,1000,c.WorldKey,prefsService,places);
  ok(sum.Resources.Count==3,"different products and exact variants stay separate");var iron=sum.Resources.Single(x=>x.Item==40&&x.Auxiliary==0);
  ok(iron.Stock==1695&&iron.Rate==81&&iron.Devices==2&&iron.KnownRates==2,"top card sums exact product stock/rate and matching device count");
  var filtered=LedgerProductionServices.Overview(LedgerDeviceSelection.Filter(devices,"Ore 40",LedgerDeviceSelection.Resource(40,0)),1000,c.WorldKey,prefsService,places);
  ok(filtered.Resources.Count==1&&filtered.Resources[0].Stock==1695&&filtered.Resources[0].Rate==81,"search and resource filters intersect for summary values");
  ok(LedgerProductionServices.Overview(LedgerDeviceSelection.Filter(devices,"no match",null),1000,c.WorldKey,prefsService,places).Resources.Count==0,"empty filters invent no rates");
  devices[0].Production.ShownQuality=null;devices[0].Production.Period=null;
  sum=LedgerProductionServices.Overview(devices,1000,c.WorldKey,prefsService,places);iron=sum.Resources.Single(x=>x.Item==40&&x.Auxiliary==0);
  ok(iron.Rate==50&&iron.KnownRates==1&&iron.RateText.Contains("?"),"partial unknown rates preserve known subtotal and uncertainty");
  var alternating=Device(c,8,50,100,4);alternating.Production.Alternating=true;alternating.Production.Outputs.Add(new LedgerProductionOutput{Item=51,Auxiliary=0,Name="Other product",Stock=3});
  ok(LedgerProductionDisplay.ProductRate(alternating.Production)==50,"known alternating outputs each receive half the cycle rate");alternating.Production.Alternating=false;
  ok(!LedgerProductionDisplay.ProductRate(alternating.Production).HasValue,"unproven multi-output sequence has no invented per-product rate");
  foreach(int width in new[]{380,650,1080,1400})foreach(int n in new[]{0,1,8,31}){bool fits=true;for(int i=0;i<n;i++){var cell=LedgerDeviceSelection.Cell(i,width);fits&=cell[0]>=0&&cell[0]+cell[2]<=width+.01&&cell[1]+cell[3]<=LedgerDeviceSelection.Height(n,width)&&cell[3]>=44;}ok(fits,"two-line summary wraps without clipping "+width+" "+n);}
  var v=new LedgerViewData{WorldKey=c.WorldKey,ManualPlayerId=1002,ManualStateReady=true};for(int i=1;i<=2048;i++)v.DiscoveredObjects.Add(LedgerDiscoveredObjects.Merge(null,Place(root,i)));
  var browser=v.PlaceBrowser;for(int i=0;i<browser.Rows.Count;i++)browser.Rows[i].TemplatePotential=i%7==0?null:new LedgerPlaceTemplate{PotentialTraders=i%5};
  var player=new LedgerPlayerPoint{World=c.WorldKey,Playfield=c.Playfield,SaveScope=c.LocalSaveKey??c.SavePath,X=0,Y=0,Z=0,Geography=c.Geography};
  var a=browser.Rows.Single(r=>r.Record.Latest.DiscoveredObject.NativeId==1);ok(browser.Distance(a,player)==10&&browser.DistanceText(a,player)=="10 m","known exact local observed-place distance");
  var sort=new LedgerHeaderSort();sort.Click(1);var rows=browser.Query(LedgerObjectOrganization.Unsorted);var cache=new LedgerPlaceSortCache();var sorted=cache.Apply(rows,browser,sort,player,0,1000);
  ok(sorted[0].Record.Latest.DiscoveredObject.NativeId==1&&sorted.Count==2048,"large distance sort retains all instances");var watch=Stopwatch.StartNew();for(int i=0;i<5000;i++)okRef(cache.Apply(rows,browser,sort,player,0,1000),sorted);watch.Stop();
  ok(cache.Rebuilds==1,"5000 repeated GUI/scroll renders do not repeat a full sort");
  var next=new LedgerPlayerPoint{World=player.World,Playfield=player.Playfield,SaveScope=player.SaveScope,X=200,Y=0,Z=0,Geography=c.Geography};cache.Apply(rows,browser,sort,next,0,1500);ok(cache.Rebuilds==1,"movement sort coalesces within one second");cache.Apply(rows,browser,sort,next,0,2000);ok(cache.Rebuilds==2,"moving distance sort refreshes on bounded cadence");
  cache.Apply(rows,browser,sort,null,0,2100);ok(cache.Rebuilds==3,"lost origin invalidates numeric ordering immediately");
  sort.Click(2);sorted=cache.Apply(rows,browser,sort,player,0,2200);ok(sorted.Last().PotentialTraders==null&&sorted.First().PotentialTraders==0,"Max Traders ascending keeps observed zero distinct from unknown");sort.Click(2);sorted=cache.Apply(rows,browser,sort,player,0,2300);ok(sorted.Last().PotentialTraders==null&&sorted.First().PotentialTraders==4,"Max Traders descending also keeps unknown last");
  var selection=new LedgerPlaceSelection();selection.Scope("all",rows);selection.Toggle(a.Record.Key);browser.Sort(rows,sort,player);ok(selection.Selected.Contains(a.Record.Key),"sorting preserves exact multiselection");selection.Scope("filtered",rows.Take(2));ok(selection.Selected.Count==0,"filter change removes invisible stale selection");
  var remote=Place(root,4000,"Fixture Delta IV Moon A");var extended=new LedgerViewData{WorldKey=v.WorldKey,ManualPlayerId=1002,ManualStateReady=true};extended.DiscoveredObjects.AddRange(v.DiscoveredObjects);extended.DiscoveredObjects.Add(LedgerDiscoveredObjects.Merge(null,remote));var updated=new LedgerPlaceBrowser(extended);var remoteRow=updated.Find(LedgerDiscoveredObjects.Key(remote));ok(updated.DistanceText(remoteRow,player)=="1.0 AU","Places uses verified shared cross-playfield formatter");
  remote.Context.Geography.SystemCoordinates="10000,0,0";remote.Context.Geography.SectorCoordinates="0,0,0";extended.DiscoveredObjects.Last().Latest.Context.Geography=remote.Context.Geography;var inter=new LedgerPlaceBrowser(extended);ok(inter.DistanceText(inter.Find(LedgerDiscoveredObjects.Key(remote)),player)=="0.1 ly","interstellar distance uses native verified conversion");
  var wrong=new LedgerPlayerPoint{World="different save",Playfield=player.Playfield,SaveScope=player.SaveScope};ok(!browser.Distance(a,wrong).HasValue,"foreign save cannot produce local numbers");
  var old=LedgerDiscoveredObjects.Merge(null,first);old.Latest.DiscoveredObject.Template=null;old.Latest.DiscoveredObject.FactionGroup=old.Latest.DiscoveredObject.FactionId=null;
  var revisited=LedgerDiscoveredObjects.Merge(old,Place(root,1));ok(revisited.Latest.DiscoveredObject.FactionGroup==7,"actual revisiting refreshes missing old metadata without backfill");
  var known=new LedgerFactionPresentation();foreach(var pair in new[]{Tuple.Create(0,LedgerPlaceRelation.Hostile,"FF5555"),Tuple.Create(1,LedgerPlaceRelation.Unfriendly,"FFAA55"),Tuple.Create(2,LedgerPlaceRelation.Neutral,"FFFF55"),Tuple.Create(3,LedgerPlaceRelation.Friendly,"55DD77"),Tuple.Create(4,LedgerPlaceRelation.Friendly,"55DD77")}){known.Level(pair.Item1,"fixture");ok(known.Relation==pair.Item2&&known.RelationColor==pair.Item3,"native relation standing and separate dot colour "+pair.Item1);}
  var none=new LedgerObjectFact{FactionGroup=255,FactionId=0};var na=LedgerPlaceFactions.Current.Resolve(none);ok(na.Relation==LedgerPlaceRelation.NotApplicable&&na.RelationLabel=="N/A","native NoFaction is inapplicable, never invented neutral");
  ok(LedgerPlaceFactions.Current.Resolve(new LedgerObjectFact()).Relation==LedgerPlaceRelation.Unknown,"missing faction/relation remains unknown");
  var market=new LedgerViewData{WorldKey=c.WorldKey,ManualPlayerId=1002};foreach(var p in new[]{c,remote.Context})market.Markets.Add(new LedgerObservation{Kind="market",Context=p,Identity=new LedgerIdentity{NpcEntityId=10+market.Markets.Count,StructureEntityId=20+market.Markets.Count,StructureName="Station",OwnerConsistent=true}});
  var index=new LedgerLocationIndex(market);ok(index.Scopes(LedgerScopeKind.Sector).All(s=>s.Label=="Fixture Delta IV"&&!s.Label.Contains("[")),"native sector labels replace debug coordinates while identities remain distinct");
  ok(index.Scopes(LedgerScopeKind.Sector).Select(s=>s.Key).Distinct().Count()==2,"same sector names never merge different systems/coordinates");
  foreach(var kind in new[]{LedgerScopeKind.Poi,LedgerScopeKind.Body,LedgerScopeKind.Sector,LedgerScopeKind.System}){var picker=new LedgerScopePicker(LedgerScopeKind.Poi){Key="old",Expanded=true};picker.Change(kind);ok(picker.Kind==kind&&(kind==LedgerScopeKind.Poi||picker.Key==null&&!picker.Expanded),"four comparison icon levels reuse exact existing picker semantics "+kind);}
  var details=new LedgerItemDetails{Description="You need a highly fertile growing plot.",Mass="1 kg",Volume="unknown",NativeStats="Crop type: Berries\nYield: 2\nGrowth time: 74 min\nMarketplace: 165\nMass: 1 kg"};string shown=LedgerItemDisplay.Details(details);
  ok(shown.Contains("growing plot")&&shown.Contains("Berries")&&shown.Contains("74 min")&&shown.Contains("165"),"shared Market/Browser formatter retains description and all crop metadata");
  ok(Regex.Matches(shown,"Mass:").Count==1&&!shown.Contains("Volume: unknown"),"native physical stats are not duplicated or filled with invented volume");
  ok(LedgerItemDisplay.SameDefinition("ElderberryStage1","ElderberryStage1")&&!LedgerItemDisplay.SameDefinition("ElderberryStage1","ElderberryStage2")&&!LedgerItemDisplay.SameDefinition(null,null),"block metadata selection requires exact canonical identity, not sprout/name similarity");
  details.NativeStats=null;ok(LedgerItemDisplay.Details(details).Contains("Volume: unknown"),"missing native stat list retains explicit physical uncertainty");
  string workspace=Environment.CurrentDirectory;Func<string,string> source=name=>File.ReadAllText(Path.Combine(workspace,"src/TradeLedgerProbeB",name));
  ok(source("LedgerNativeCatalog.cs").Contains("0x04001488")&&source("LedgerNativeCatalog.cs").Contains("PropertyRoots")&&source("LedgerNativeItemDetails.cs").Contains("new[]{primary,sharedProperties,null,null}"),"shared actual reader supplies audited block property root to native formatter");
  ok(source("LedgerNativeCatalog.cs").Contains("propertyRoots.TryGetValue")&&source("LedgerNativeCatalog.cs").Contains("propertyRoots.Clear()"),"native definition roots cached per catalogue refresh, not re-reflected per property");
  ok(!source("LedgerBrowserWindow.cs").Contains("graph-frame")&&source("LedgerBrowserWindow.cs").Contains("Center selected")&&source("LedgerBrowserWindow.cs").Contains("DrawBrowserInformation(side)"),"browser explicit framing buttons and right-column details wired");
  ok(source("LedgerPlaceBrowserWindow.cs").Contains("placeRelationColors")&&source("LedgerJournalUiWindow.cs").Contains("uiMenuColors[i]"),"relation filter items themselves receive their distinct colours");
  ok(!source("LedgerPlaceBrowserWindow.cs").Contains("row.FactionInfo.RelationLabel"),"place rows do not repeat relation text beside dots");
  foreach(var file in Directory.GetFiles(Path.Combine(workspace,"src/TradeLedgerProbeB"),"*Window.cs"))ok(!Regex.IsMatch(File.ReadAllText(file),"\"[^\"\r\n]* v\""),"no literal v dropdown suffix "+Path.GetFileName(file));
  ok(source("LedgerPrototypeWindow.cs").Contains("verticalScrollbarThumb.padding=new RectOffset(0,0,6,6)")&&source("LedgerPrototypeWindow.cs").Contains("normal.background=thumb"),"scrollbar thumb has contrast and minimum geometry for long lists");
  var dir=Path.Combine(root,"ui-consistency");Directory.CreateDirectory(dir);
