   ok(panel.GraphWidth>150&&panel.DetailsWidth>150&&panel.GraphWidth+panel.DetailsWidth+12<=available+.01,"browser panels fit supported resolution "+width);
   ok(panel.GraphHeight>layout.Height-112-280,"graph gains height from right-column details "+width);
