  }
  File.WriteAllText(Path.Combine(dir,"checks.txt"),count+" checks; 2048 places,5000 warm refreshes in "+watch.Elapsed.TotalMilliseconds.ToString("0.00",CultureInfo.InvariantCulture)+"ms; shared geometry/model/GDI only; Library originals inaccessible; Unity not run");
  Console.WriteLine("UI consistency checks passed: "+count+"; previews: "+dir);
